function show() {
  const rows = {
    "innerWidth x innerHeight": innerWidth + " x " + innerHeight,
    "screen width x height": screen.width + " x " + screen.height,
    "navigator.language": navigator.language,
    "navigator.onLine": navigator.onLine,
    "navigator.cookieEnabled": navigator.cookieEnabled,
    "location.protocol": location.protocol,
    "location.pathname": location.pathname,
    "history.length": history.length,
  };
  document.getElementById("info").innerHTML = Object.entries(rows)
    .map(([k, v]) => `<tr><td>${k}</td><td>${String(v)}</td></tr>`).join("");
}
show();
document.getElementById("refresh").addEventListener("click", show);
addEventListener("resize", show);

