const out = document.getElementById("out");
const safe = (fn) => { try { return fn(); } catch (e) { out.textContent = "Storage unavailable: " + e.name; } };

safe(() => {
  const visits = Number(localStorage.getItem("visits") || 0) + 1;
  localStorage.setItem("visits", String(visits));
  document.getElementById("visits").textContent = visits;
});
document.getElementById("save").addEventListener("click", () =>
  safe(() => {
    localStorage.setItem("profile", JSON.stringify({ name: "Vinod", age: 30, city: "pune" }));
    out.textContent = "Saved!";
  })
);
document.getElementById("load").addEventListener("click", () =>
  safe(() => {
    const p = JSON.parse(localStorage.getItem("profile"));
    out.textContent = p ? JSON.stringify(p, null, 2) : "Nothing saved yet";
  })
);
document.getElementById("clear").addEventListener("click", () =>
  safe(() => { localStorage.clear(); out.textContent = "Cleared"; })
);

