const result = document.getElementById("result");
const messages = { 1: "Permission denied", 2: "Position unavailable", 3: "Request timed out" };

document.getElementById("where").addEventListener("click", () => {
  if (!("geolocation" in navigator)) {
    result.textContent = "Geolocation is not supported";
    return;
  }
  result.textContent = "Locating...";
  navigator.geolocation.getCurrentPosition(
    ({ coords }) => {
      result.textContent = `Lat ${coords.latitude.toFixed(4)}, Lng ${coords.longitude.toFixed(4)} (+/- ${Math.round(coords.accuracy)} m)`;
    },
    (err) => { result.textContent = messages[err.code] || err.message; },
    { timeout: 8000, maximumAge: 60000 }
  );
});
